text:
/* Editor-only layout; the library and other workspace routes keep their sizing. */
html:has(.template-editor-page) {
  --template-editor-glow: radial-gradient(
    900px 500px at 12% 0%,
    color-mix(in srgb, var(--accent) 12%, transparent),
    transparent 65%
  );
  --template-editor-bar: color-mix(in srgb, var(--background) 90%, transparent);
  background: var(--background);
}
html[data-appearance="vercel"][data-theme="light"]:has(.template-editor-page) {
  --template-editor-glow: none;
}
html[data-appearance="vercel"][data-theme="dark"]:has(.template-editor-page) {
  --template-editor-glow: radial-gradient(
    900px 500px at 50% 0%,
    color-mix(in srgb, var(--foreground) 6%, transparent),
    transparent 65%
  );
}
html[data-workspace] body:has(.template-editor-page) {
  min-height: 100vh;
  min-height: 100dvh;
  background:
    var(--template-editor-glow) fixed,
    var(--background);
}
html[data-workspace] main.page-container:has(.template-editor-page) {
  max-width: 1480px;
  padding-inline: clamp(16px, 3vw, 40px);
  padding-bottom: 180px;
}
.page-transition:has(.template-editor-page) {
  /* A transformed ancestor would contain the viewport-fixed action bar. */
  animation: none;
}
.template-editor .placeholder-chip {
  min-height: 36px;
  padding: 5px 10px;
  font-size: 12px;
  color: var(--link);
  background: var(--accent-soft);
  border-color: var(--border);
}
.template-editor .placeholder-chip:hover {
  background: color-mix(in srgb, var(--accent) 18%, var(--card));
}
.template-editor :is(input:not([type="hidden"]), textarea, select) {
  background: var(--surface);
  color: var(--foreground);
  border-color: var(--input-boundary, var(--control-border));
}
.template-editor-actions button[type="submit"] {
  background: var(--button-gradient);
  color: var(--button-foreground);
}
.template-editor
  :is(button, a, input, textarea, select, [tabindex]):focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
}
@media (prefers-reduced-transparency: reduce) {
  .template-editor-action-bar {
    background: var(--background);
    backdrop-filter: none;
  }
}
body:has(.template-editor-page) .help-launcher {
  bottom: max(88px, calc(env(safe-area-inset-bottom) + 76px));
}
@media (max-width: 959px) {
  body:has(.template-editor-page) .help-launcher {
    bottom: max(200px, calc(env(safe-area-inset-bottom) + 188px));
  }
  body:has(.template-editor-page) .success-toast {
    bottom: max(260px, calc(env(safe-area-inset-bottom) + 248px));
  }
  html[data-workspace] main.page-container:has(.template-editor-page) {
    padding-bottom: 240px;
  }
}
html[data-workspace]
  .template-editor
  .template-editor-actions
  button[type="submit"]:disabled {
  background: var(--surface);
  color: var(--body);
  border: 1px solid var(--control-border);
  box-shadow: none;
  filter: none;
  opacity: 1;
  cursor: not-allowed;
}
